<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Holder\UserBlockedUntilAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserBlockedUntilAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserBlockedUntilAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getBlockedUntil returns null on a freshly created holder.
     */
    public function testBlockedUntilNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserBlockedUntilAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isBlockedUntilAssigned());
        $this->assertNull($holder->getBlockedUntil());
    }
}
class ImplWithUserBlockedUntilAttributeHolderUnitTest
{
    use UserBlockedUntilAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedBlockedUntilRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultBlockedUntil();
    }
}
